const $=id=>document.getElementById(id);let data=[];let saved=[];try{saved=JSON.parse(localStorage.getItem('resourceful-ymca-favorites')||'[]');if(!Array.isArray(saved))saved=[]}catch{}const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function section(s){return `<div class="hour-section"><h5>${esc(s.title)}</h5>${s.warning?`<p class="warning">${esc(s.warning)}</p>`:''}${s.lines.map(l=>`<p>${esc(l)}</p>`).join('')}</div>`}
function render(){let q=$('search').value.trim().toLowerCase();let list=data.filter(b=>(!q||[b.name,b.city,b.address].join(' ').toLowerCase().includes(q))&&(!$('city').value||b.city===$('city').value)&&(!$('kids').checked||b.hasKids)&&(!$('indoor').checked||b.hasIndoor)&&(!$('favorites').checked||saved.includes(b.id)));$('count').textContent=`${list.length} of ${data.length} locations`;$('locations').innerHTML=list.length?list.map(b=>{let branch=b.sections.filter(s=>s.title==='Branch Hours'),kids=b.sections.filter(s=>s.title.startsWith('Kid Zone')),pools=b.sections.filter(s=>/Pool|Swim/.test(s.title));return `<article class="card"><div class="card-head"><div class="card-title"><div class="eyebrow">${esc(b.city)}</div><h3>${esc(b.name)}</h3><p>${esc(b.address)}</p><div class="tags">${b.hasKids?'<span class="tag">Kid Zone</span>':''}${b.amenities.filter(a=>['Indoor Pool','Outdoor Pool','Toddler Pool'].includes(a)).map(a=>`<span class="tag">${esc(a)}</span>`).join('')}</div><div class="links"><a href="${esc(b.hoursUrl)}" target="_blank" rel="noopener">Official hours ↗</a><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(b.address+' '+b.name)}" target="_blank" rel="noopener">Directions ↗</a><a href="tel:${esc(b.phone.replace(/[^+0-9]/g,''))}">${esc(b.phone)}</a></div></div><button class="star" data-id="${esc(b.id)}" aria-label="Favorite ${esc(b.name)}" aria-pressed="${saved.includes(b.id)}">${saved.includes(b.id)?'★':'☆'}</button></div><details${b.city==='Durham'?' open':''}><summary>Branch, Kid Zone & pool hours</summary><div class="hours-grid"><div><h4>Branch</h4>${branch.map(section).join('')||'<p class="empty">Branch hours not published. Check official hours.</p>'}</div><div><h4>Kid Zone</h4>${kids.map(section).join('')||`<p class="empty">${b.hasKids?'Hours not published. Check with the branch.':'Not listed as an amenity at this location.'}</p>`}</div><div><h4>Pools</h4>${pools.map(section).join('')||`<p class="empty">${b.hasPool?'Pool hours not published. Check the official schedule.':'No on-site pool listed.'}</p>`}${b.hasPool?'<a class="meta" href="https://ymcatriangle.org/schedules" target="_blank" rel="noopener">Live lane & family-swim schedule ↗</a>':''}</div></div></details></article>`}).join(''):'<p class="empty">No matching locations. Try another search or reset your filters.</p>'}
$('locations').addEventListener('click',e=>{const button=e.target.closest('[data-id]');if(!button)return;const id=button.dataset.id;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('resourceful-ymca-favorites',JSON.stringify(saved))}catch{}render()});['search','city','kids','indoor','favorites'].forEach(id=>$(id).addEventListener('input',render));$('reset').addEventListener('click',()=>{$('search').value='';$('city').value='';['kids','indoor','favorites'].forEach(id=>$(id).checked=false);render()});fetch('ymca-data.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(rows=>{data=rows.sort((a,b)=>(a.city==='Durham'?-1:0)-(b.city==='Durham'?-1:0)||a.name.localeCompare(b.name));[...new Set(data.map(x=>x.city))].sort().forEach(c=>{const o=document.createElement('option');o.value=c;o.textContent=c;$('city').append(o)});render()}).catch(()=>{$('count').textContent='Unable to load locations.';$('locations').innerHTML='<p>Please reload or visit <a href="https://ymcatriangle.org/locations">the official YMCA directory</a>.</p>'});
